window.PROBLEM_LESSONS["react-02"] = {"parts": [{"part": 1, "steps": [{"explanation": "Keep the stream as source state and subscribe exactly once. A functional state update avoids closing over a stale array; deriving and sorting active rows leaves the received records untouched.", "code": "const [incidents, setIncidents] = useState([])\n\nuseEffect(() => {\n  return incidentFeed.subscribe(incident => {\n    setIncidents(current => [incident, ...current])\n  })\n}, [])\n\nconst activeIncidents = incidents\n  .filter(incident => !incident.contained)\n  .sort((a, b) => Date.parse(b.ts) - Date.parse(a.ts))\n\nfunction relativeTime(ts) {\n  const minutes = Math.max(0, Math.floor((Date.now() - Date.parse(ts)) / 60_000))\n  return `${minutes} min ago`\n}", "rejected": "Putting the feed connection in this component would duplicate App's ownership. Mutating SEED_INCIDENTS or sorting the state array in place would corrupt shared/source data."}, {"explanation": "Render the contract directly, including the required test IDs. The severity map is presentation data, so it can style the badge without adding another state variable.", "code": "{activeIncidents.map(incident => (\n  <article key={incident.id} data-testid=\"incident-row\">\n    <span data-testid=\"severity-badge\" style={SEVERITY_COLORS[incident.severity]}>\n      {incident.severity}\n    </span>\n    <strong>{incident.type}</strong> · {incident.location}\n    <small>{relativeTime(incident.ts)}</small>\n  </article>\n))}\n{activeIncidents.length === 0 && <p>No incidents yet.</p>}"}]}, {"part": 2, "steps": [{"explanation": "Filters describe the view, not the feed. Store each selection independently and memoize a projection from incidents plus those selections; the subscription effect still has no filter dependency and therefore never restarts.", "code": "const [severityFilter, setSeverityFilter] = useState('all')\nconst [typeFilter, setTypeFilter] = useState('all')\n\nconst visibleIncidents = useMemo(() => incidents\n  .filter(incident => !incident.contained)\n  .filter(incident => severityFilter === 'all' || incident.severity === severityFilter)\n  .filter(incident => typeFilter === 'all' || incident.type === typeFilter)\n  .sort((a, b) => Date.parse(b.ts) - Date.parse(a.ts)),\n  [incidents, severityFilter, typeFilter]\n)", "rejected": "Deleting nonmatching incidents from state loses information and makes changing a filter irreversible. Adding filters to the effect dependency list tears down and recreates the subscription."}, {"explanation": "Controlled selects make the state-to-view relationship visible and give the count for free from the memoized array.", "code": "<label>Severity <select data-testid=\"filter-severity\" value={severityFilter} onChange={event => setSeverityFilter(event.target.value)}>\n  <option value=\"all\">all</option>\n  {SEVERITIES.map(value => <option key={value} value={value}>{value}</option>)}\n</select></label>\n<label>Type <select data-testid=\"filter-type\" value={typeFilter} onChange={event => setTypeFilter(event.target.value)}>\n  <option value=\"all\">all</option>\n  {INCIDENT_TYPES.map(value => <option key={value} value={value}>{value}</option>)}\n</select></label>\n<span>{visibleIncidents.length} visible</span>"}]}, {"part": 3, "steps": [{"explanation": "Pending and errors are per incident because requests can overlap. Optimistically flip only the chosen record, then merge success or rollback into the latest state with functional updates.", "code": "const [pendingIds, setPendingIds] = useState(() => new Set())\nconst [errors, setErrors] = useState({})\n\nconst handleContain = useCallback(async id => {\n  setPendingIds(current => new Set(current).add(id))\n  setErrors(current => ({ ...current, [id]: undefined }))\n  setIncidents(current => current.map(item => item.id === id ? { ...item, contained: true } : item))\n  try {\n    await containIncident(id)\n  } catch (_) {\n    setIncidents(current => current.map(item => item.id === id ? { ...item, contained: false } : item))\n    setErrors(current => ({ ...current, [id]: 'Failed — retry' }))\n  } finally {\n    setPendingIds(current => { const next = new Set(current); next.delete(id); return next })\n  }\n}, [])", "rejected": "A single loading Boolean disables every row. Restoring a captured incidents array on failure can erase records that arrived while the request was in flight."}, {"explanation": "Revise the active projection to retain an optimistically contained row while its request is pending; otherwise the disabled button disappears immediately. Confirmed records then move to the separate derived section.", "code": "// In visibleIncidents, replace the active filter with:\n.filter(incident => !incident.contained || pendingIds.has(incident.id))\n\nconst confirmedContained = incidents.filter(item => item.contained && !pendingIds.has(item.id))\n\n<button data-testid=\"contain-btn\" disabled={pendingIds.has(incident.id)} onClick={() => handleContain(incident.id)}>\n  {pendingIds.has(incident.id) ? 'Containing…' : 'Contain'}\n</button>\n{errors[incident.id] && <span>{errors[incident.id]}</span>}\n\n<section><h3>Contained</h3>{confirmedContained.map(incident => (\n  <article key={incident.id} data-testid=\"contained-row\">{incident.type} · {incident.location}</article>\n))}</section>"}]}], "reflection": "The core React lesson is to separate source state, derived display state, and transient request state. Effects own external lifecycles, memoized projections own filtering, and functional updates make asynchronous optimistic work compose safely with a continuing stream."};
